def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    opp_d = sum(1 for x in op if x == 'D')
    my_d = sum(1 for x in my if x == 'D')

    first_def = -1
    for i in range(n):
        if my[i] == 'D' or op[i] == 'D':
            first_def = i
            break
    we_defected_first = (first_def != -1 and my[first_def] == 'D')

    if last_op == 'D':
        if we_defected_first:
            if opp_d <= 3:
                if rng.random() < 0.7:
                    return 'C'
            elif opp_d <= 6:
                if rng.random() < 0.3:
                    return 'C'
            return 'D'
        else:
            if opp_d <= 2 and n > 20:
                if rng.random() < 0.3:
                    return 'C'
            return 'D'

    if last_my == 'D':
        ret_count = 0
        my_d_count = 0
        for i in range(n-1):
            if my[i] == 'D':
                my_d_count += 1
                if op[i+1] == 'D':
                    ret_count += 1
        if my_d_count >= 2:
            ret_rate = ret_count / my_d_count
            if ret_rate < 0.3:
                if rng.random() < 0.6:
                    return 'D'
            return 'C'
        else:
            return 'C'

    if opp_d == 0:
        if n >= 20:
            return 'D'
        elif n >= 5:
            if rng.random() < 0.4:
                return 'D'
        return 'C'

    ret_count = 0
    my_d_count = 0
    for i in range(n-1):
        if my[i] == 'D':
            my_d_count += 1
            if op[i+1] == 'D':
                ret_count += 1
    if my_d_count >= 3:
        ret_rate = ret_count / my_d_count
        if ret_rate < 0.2:
            if rng.random() < 0.5:
                return 'D'
        elif ret_rate < 0.5:
            if rng.random() < 0.2:
                return 'D'
        else:
            if n % 15 == 0 and n > 10:
                return 'D'
            return 'C'
    else:
        if n % 8 == 0 and n > 5:
            return 'D'
        return 'C'

    return 'C'
